call.example:
var st = PCS.stage({ name: 'BEAT 3', duration: 5 });
var pill = PCS.plate(st.comp, { name: 'pill', w: 780, h: 160, round: 80, pos: [540, 300, 0] });
PCS.flip(pill, { t: 1.2, axis: 'x' });
PCS.flip(pill, { t: 3.0, axis: 'x' });   // and back: moves chain on one object

var st = PCS.stage({ name: 'BEAT 4', duration: 6, stitch: { path: 'stitch.mp4', start: 12.4 } });
var tile = PCS.plate(st.comp, { name: 'tile', w: 300, h: 300, round: 56, color: PCS.S.accent, pos: [540, 560, 0] });
var rm = PCS.handOver(st, { t: 2.0, carry: tile, to: [540, 1349, 700] });
PCS.spot(rm.comp, { name: 'pool', on: tile, from: 'above', t: 3.0, dimKey: 0.5 });

var yes = PCS.type3d(st.comp, { text: 'Yes', size: 240, pos: [770, 640, 0] });
PCS.hideUntil(yes, 1.0);
PCS.hideAfter(yes, 2.9);

var tile = PCS.twoSided(st.comp, { name: 'tile', w: 360, h: 360, round: 64, color: PCS.S.accent, backColor: PCS.S.quiet, pos: [540, 846, 0] });
PCS.flip(tile.front, { t: 0.84, dur: 0.5 });
PCS.move(tile.front, { t: 0.84, dur: 0.5, to: [540, 560], scale: 150, overshoot: 6 });   // grows and rises into the question as it turns

var card = PCS.plate(st.comp, { name: 'card', w: 600, h: 360, round: 34, pos: [540, 500, 0] });
PCS.onFace(PCS.label(st.comp, { text: 'Question', size: 80, on: 'surface' }), card);
PCS.onBack(PCS.label(st.comp, { text: 'Answer', size: 80, on: 'surface' }), card, [0, 0], 'x');
PCS.flip(card, { t: 1.2, axis: 'x' });

var rm = PCS.room({ name: 'CUTAWAY 2', duration: 5 });
var card = PCS.plate(rm.comp, { name: 'card', w: 560, h: 380, round: 30, tilt: [0, -10], pos: rm.stand(380, 540, 700) });
PCS.spot(rm.comp, { name: 'pool', on: card, from: 'above', t: 1.2, dimKey: 0.4 });

var st = PCS.stage({ name: 'BEAT 3', duration: 5 });
var card = PCS.plate(st.comp, { name: 'card', w: 400, h: 520, round: 34, pos: [790, 720, 0] });
PCS.spot(st.comp, { name: 'pool', on: card, t: 2.6, dimKey: 0.6 });

var card = PCS.plate(st.comp, { name: 'card', w: 720, h: 470, round: 34, pos: [540, 900, 0] });
PCS.onFace(PCS.label(st.comp, { text: '42 passed, 0 failed', size: 52, on: 'surface' }), card);
PCS.standUp(card, { t: 2.6 });

PCS.onFace(first, card); PCS.onFace(second, card);
PCS.flip(card, { t: 1.0, axis: 'x' }); PCS.flip(card, { t: 2.0, axis: 'x' });
PCS.swapFace(first, second, 1.7);   // while the front is turned away

var tile = PCS.twoSided(st.comp, { name: 'tile', w: 330, h: 330, round: 60, color: PCS.S.quiet, backColor: PCS.S.accent, pos: [300, 640, 0] });
PCS.onFace(PCS.label(st.comp, { text: '?', size: 190 }), tile.front);
PCS.onFace(PCS.tick(st.comp, { size: 280, t: 1.0 }), tile.back);
PCS.flip(tile.front, { t: 0.8 });

var q = PCS.words(st.comp, { words: [{ text: 'is', t: 1.4 }, { text: 'it', t: 1.6 }, { text: 'right?', t: 1.9 }], size: 84, under: tile });
var line = PCS.words(st.comp, { words: [{ text: 'Ask', t: 1.5 }, { text: 'for', t: 1.9 }, { text: 'proof', t: 2.1 }], size: 80, on: 'surface' });
PCS.onFace(line.holder, card);
